def bfs(initial, goal, present, allowed, max_depth=3):
    # Independently expressed integer state: (light, fan), levels 0/1/2.
    levels = {"off": 0, "low": 1, "high": 2}
    start = (levels[initial["light"]], levels[initial["fan"]])
    def valid(state):
        light, fan = state
        return ((present or light == 0) and
                (present or fan != 2) and light + fan <= 3 and
                (fan != 2 or light >= 1))
    wanted = {0 if k == "light" else 1: levels[v] for k, v in goal.items()}
    if not valid(start):
        return {"initial_legal": False, "reachable": False, "witness": None}
    queue = deque([(start, [])]); seen = {start}
    while queue:
        state, path = queue.popleft()
        if all(state[k] == v for k, v in wanted.items()):
            return {"initial_legal": True, "reachable": True,
                    "minimum_writes": len(path), "witness": path,
                    "terminal_state": {"light": tuple(levels)[state[0]], "fan": tuple(levels)[state[1]]}}
        if len(path) == max_depth:
            continue
        for index, device in enumerate(("light", "fan")):
            if device not in allowed:
                continue
            for value, numeric in levels.items():
                if state[index] == numeric or (state[index] == 0 and numeric == 2):
                    continue
                after = list(state); after[index] = numeric; after = tuple(after)
                if not valid(after) or after in seen:
                    continue
                seen.add(after)
                queue.append((after, path + [{"device": device, "value": value}]))
    return {"initial_legal": True, "reachable": False, "witness": None}
